// // // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellCenter}>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 <button
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     onClick={() => handleUpdateItem(item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={{ ...styles.actionButton, color: '#4CAF50' }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     title="Save"
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             handleUpdateItem(item.id);
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     <FiCheck size={14} />
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 </button>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 <button
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     onClick={handleCancelEdit}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={{ ...styles.actionButton, color: '#f44336' }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     title="Cancel"
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             handleCancelEdit();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     <FiX size={14} />
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 </button>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         </tr>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                     );
// // // // // // // // // // // // // // // // // // // // // // // // // //                                 }

// // // // // // // // // // // // // // // // // // // // // // // // // //                                 return (
// // // // // // // // // // // // // // // // // // // // // // // // // //                                     <tr key={item.id} style={{ borderBottom: '1px solid #eee', opacity: validItem ? 1 : 0.6 }} data-item-row>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCell}>{index + 1}</td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCell}>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                             {item.item_name ? (
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 <>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     <strong>{item.item_name}</strong>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     {item.item_name_urdu && (
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         <div style={{ fontSize: '10px', color: '#666', direction: 'rtl' }}>{item.item_name_urdu}</div>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     )}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 </>
