// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.quantity || 0}</td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.rate ? `₨ ${item.rate.toLocaleString()}` : '-'}</td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.amount ? `₨ ${item.amount.toLocaleString()}` : '-'}</td>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellCenter}>
// // // // // // // // // // // // // // // // // // // // // // // // // //                                             <button
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 data-edit-btn
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 onClick={() => handleEditItem(item)}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 style={{ ...styles.actionButton, color: '#2196F3' }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 title="Edit"
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         handleEditItem(item);
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     } else if (e.key === 'ArrowDown') {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         const nextRow = e.target.closest('tr').nextElementSibling;
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (nextRow && nextRow.querySelector('[data-edit-btn]')) {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             nextRow.querySelector('[data-edit-btn]').focus();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         } else if (!nextRow) {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             addItemRowButtonRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     } else if (e.key === 'ArrowUp') {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         const prevRow = e.target.closest('tr').previousElementSibling;
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (prevRow && prevRow.querySelector('[data-edit-btn]')) {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             prevRow.querySelector('[data-edit-btn]').focus();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         } else if (!prevRow) {
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                             notesRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                     }
// // // // // // // // // // // // // // // // // // // // // // // // // //                                                 }}
// // // // // // // // // // // // // // // // // // // // // // // // // //                                             >
