// // // // // // // // // // // // // // // // // // // // // // // // //                     />
// // // // // // // // // // // // // // // // // // // // // // // // //                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //             </div>

// // // // // // // // // // // // // // // // // // // // // // // // //             {/* Rest of the component remains the same */}
// // // // // // // // // // // // // // // // // // // // // // // // //             <div style={styles.card}>
// // // // // // // // // // // // // // // // // // // // // // // // //                 <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <h3 style={{ margin: 0, fontSize: '14px', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '8px' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <FiPackage size={16} /> Items
// // // // // // // // // // // // // // // // // // // // // // // // //                     </h3>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <button
// // // // // // // // // // // // // // // // // // // // // // // // //                         ref={addItemRowButtonRef}
// // // // // // // // // // // // // // // // // // // // // // // // //                         onClick={handleAddNewRow}
// // // // // // // // // // // // // // // // // // // // // // // // //                         style={styles.addButton}
// // // // // // // // // // // // // // // // // // // // // // // // //                         onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                             if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 handleAddNewRow();
// // // // // // // // // // // // // // // // // // // // // // // // //                             } else if (e.key === 'ArrowDown') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const firstItemRow = document.querySelector('[data-item-row]');
// // // // // // // // // // // // // // // // // // // // // // // // //                                 if (firstItemRow) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     const editBtn = firstItemRow.querySelector('[data-edit-btn]');
// // // // // // // // // // // // // // // // // // // // // // // // //                                     if (editBtn) editBtn.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }
// // // // // // // // // // // // // // // // // // // // // // // // //                             } else if (e.key === 'ArrowUp') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 discountRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                             }
// // // // // // // // // // // // // // // // // // // // // // // // //                         }}
// // // // // // // // // // // // // // // // // // // // // // // // //                     >
// // // // // // // // // // // // // // // // // // // // // // // // //                         <FiPlus size={14} /> Add Item Row (Ctrl+Alt+N)
// // // // // // // // // // // // // // // // // // // // // // // // //                     </button>
// // // // // // // // // // // // // // // // // // // // // // // // //                 </div>

// // // // // // // // // // // // // // // // // // // // // // // // //                 <div style={{ overflowX: 'auto' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <table style={styles.table}>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <thead>
// // // // // // // // // // // // // // // // // // // // // // // // //                             <tr style={styles.tableHeader}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCell}>#</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCell}>Item</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Qty</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Rate (₨)</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Amount (₨)</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellCenter}>Actions</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                             </tr>
// // // // // // // // // // // // // // // // // // // // // // // // //                         </thead>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <tbody>
// // // // // // // // // // // // // // // // // // // // // // // // //                             {invoice.items.map((item, index) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const isEditing = editingItemId === item.id;
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const validItem = item.item_id && item.quantity > 0;

// // // // // // // // // // // // // // // // // // // // // // // // //                                 if (isEditing && tempItem) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     return (
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <tr key={item.id} style={{ background: '#f9f9f9', borderTop: '2px solid #2196F3' }} data-item-row>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCell}>{index + 1}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCell}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <div style={styles.dropdown}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <div style={{ position: 'relative' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <FiSearch style={{ position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)', color: '#999', fontSize: '14px' }} />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <input
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             data-row-id={item.id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             data-item-search
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             type="text"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             placeholder="Search item by name or code..."
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             value={tempItem.searchTerm || ''}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onChange={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 setTempItem(prev => ({ ...prev, searchTerm: e.target.value }));
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 setShowItemDropdown(item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onFocus={() => setShowItemDropdown(item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 if (e.key === 'ArrowDown' && showItemDropdown === item.id && filteredProducts.length > 0) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     setFocusedDropdownIndex(0);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Escape') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     setShowItemDropdown(null);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Enter' && showItemDropdown === item.id && focusedDropdownIndex >= 0) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     const selected = filteredProducts[focusedDropdownIndex];
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     if (selected) handleProductSelect(selected, item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Tab' && !e.shiftKey) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     const qtyInput = document.querySelector(`[data-qty-input="${item.id}"]`);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     if (qtyInput) qtyInput.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             style={{ ...styles.input, paddingLeft: '32px' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     {showItemDropdown === item.id && filteredProducts.length > 0 && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <div
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             ref={el => itemDropdownRefs.current[item.id] = el}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             style={styles.dropdownList}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             {filteredProducts.map((product, idx) => (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 <div
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     key={product.item_id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     onClick={() => handleProductSelect(product, item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     style={{ ...styles.dropdownItem, backgroundColor: focusedDropdownIndex === idx ? '#f0f0f0' : 'white' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     onMouseEnter={() => setFocusedDropdownIndex(idx)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     <div><strong>{product.item_name}</strong></div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     <small style={{ color: '#666' }}>Code: {product.item_code} | ₨ {product.price?.toLocaleString()}</small>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             ))}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 {tempItem.item_name && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <div style={{ marginTop: '4px', fontSize: '11px', color: '#4CAF50' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         ✓ {tempItem.item_name}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellRight}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <input
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     data-qty-input={item.id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     type="number"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     value={tempItem.quantity}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onChange={(e) => handleQuantityChange(item.id, e.target.value)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     min="1"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     step="1"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={styles.smallInput}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             const rateInput = document.querySelector(`[data-rate-input="${item.id}"]`);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             if (rateInput) rateInput.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         } else if (e.key === 'Tab' && e.shiftKey) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             const itemInput = document.querySelector(`[data-row-id="${item.id}"]`);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             if (itemInput) itemInput.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 />
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellRight}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <input
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     data-rate-input={item.id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     type="number"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     value={tempItem.rate}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onChange={(e) => handleRateChange(item.id, e.target.value)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     min="0"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     step="0.01"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={styles.smallInput}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             handleUpdateItem(item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 />
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellRight}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <strong>₨ {tempItem.amount.toLocaleString()}</strong>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellCenter}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <button
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onClick={() => handleUpdateItem(item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={{ ...styles.actionButton, color: '#4CAF50' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     title="Save"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             handleUpdateItem(item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <FiCheck size={14} />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 </button>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <button
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onClick={handleCancelEdit}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     style={{ ...styles.actionButton, color: '#f44336' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     title="Cancel"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             handleCancelEdit();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <FiX size={14} />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 </button>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         </tr>
// // // // // // // // // // // // // // // // // // // // // // // // //                                     );
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }

// // // // // // // // // // // // // // // // // // // // // // // // //                                 return (
// // // // // // // // // // // // // // // // // // // // // // // // //                                     <tr key={item.id} style={{ borderBottom: '1px solid #eee', opacity: validItem ? 1 : 0.6 }} data-item-row>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCell}>{index + 1}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCell}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             {item.item_name ? (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <strong>{item.item_name}</strong>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     {item.item_name_urdu && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <div style={{ fontSize: '10px', color: '#666', direction: 'rtl' }}>{item.item_name_urdu}</div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 </>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             ) : (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <span style={{ color: '#999', fontStyle: 'italic' }}>Click edit to select item</span>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                         </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.quantity || 0}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.rate ? `₨ ${item.rate.toLocaleString()}` : '-'}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellRight}>{item.amount ? `₨ ${item.amount.toLocaleString()}` : '-'}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <td style={styles.tableCellCenter}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <button
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 data-edit-btn
