// // // // // // // // // // // // // // // // // // // // // // // // //                     }
// // // // // // // // // // // // // // // // // // // // // // // // //                 }
// // // // // // // // // // // // // // // // // // // // // // // // //             });
// // // // // // // // // // // // // // // // // // // // // // // // //         };

// // // // // // // // // // // // // // // // // // // // // // // // //         document.addEventListener('mousedown', handleClickOutside);
// // // // // // // // // // // // // // // // // // // // // // // // //         return () => document.removeEventListener('mousedown', handleClickOutside);
// // // // // // // // // // // // // // // // // // // // // // // // //     }, []);

// // // // // // // // // // // // // // // // // // // // // // // // //     // Calendar component for date picker
// // // // // // // // // // // // // // // // // // // // // // // // //     const DatePickerCalendar = () => {
// // // // // // // // // // // // // // // // // // // // // // // // //         const [currentDate, setCurrentDate] = useState(parseDate(formatDateForDisplay(invoice.invoice_date)) || new Date());

// // // // // // // // // // // // // // // // // // // // // // // // //         const getDaysInMonth = (date) => {
// // // // // // // // // // // // // // // // // // // // // // // // //             const year = date.getFullYear();
// // // // // // // // // // // // // // // // // // // // // // // // //             const month = date.getMonth();
// // // // // // // // // // // // // // // // // // // // // // // // //             const firstDay = new Date(year, month, 1);
// // // // // // // // // // // // // // // // // // // // // // // // //             const lastDay = new Date(year, month + 1, 0);
// // // // // // // // // // // // // // // // // // // // // // // // //             const days = [];

// // // // // // // // // // // // // // // // // // // // // // // // //             // Add empty cells for days before first day of month
// // // // // // // // // // // // // // // // // // // // // // // // //             for (let i = 0; i < firstDay.getDay(); i++) {
// // // // // // // // // // // // // // // // // // // // // // // // //                 days.push(null);
// // // // // // // // // // // // // // // // // // // // // // // // //             }

// // // // // // // // // // // // // // // // // // // // // // // // //             // Add days of month
// // // // // // // // // // // // // // // // // // // // // // // // //             for (let i = 1; i <= lastDay.getDate(); i++) {
// // // // // // // // // // // // // // // // // // // // // // // // //                 days.push(new Date(year, month, i));
// // // // // // // // // // // // // // // // // // // // // // // // //             }

// // // // // // // // // // // // // // // // // // // // // // // // //             return days;
// // // // // // // // // // // // // // // // // // // // // // // // //         };

// // // // // // // // // // // // // // // // // // // // // // // // //         const days = getDaysInMonth(currentDate);
// // // // // // // // // // // // // // // // // // // // // // // // //         const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

// // // // // // // // // // // // // // // // // // // // // // // // //         const isSelectedDate = (date) => {
// // // // // // // // // // // // // // // // // // // // // // // // //             if (!date) return false;
// // // // // // // // // // // // // // // // // // // // // // // // //             const selectedDate = parseDate(formatDateForDisplay(invoice.invoice_date));
// // // // // // // // // // // // // // // // // // // // // // // // //             return selectedDate && date.toDateString() === selectedDate.toDateString();
// // // // // // // // // // // // // // // // // // // // // // // // //         };

// // // // // // // // // // // // // // // // // // // // // // // // //         const handlePrevMonth = () => {
// // // // // // // // // // // // // // // // // // // // // // // // //             setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
// // // // // // // // // // // // // // // // // // // // // // // // //         };

// // // // // // // // // // // // // // // // // // // // // // // // //         const handleNextMonth = () => {
// // // // // // // // // // // // // // // // // // // // // // // // //             setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
// // // // // // // // // // // // // // // // // // // // // // // // //         };

// // // // // // // // // // // // // // // // // // // // // // // // //         return (
// // // // // // // // // // // // // // // // // // // // // // // // //             <div style={calendarStyles.container} ref={datePickerRef}>
// // // // // // // // // // // // // // // // // // // // // // // // //                 <div style={calendarStyles.header}>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <button onClick={handlePrevMonth} style={calendarStyles.navButton}>←</button>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <span style={calendarStyles.monthYear}>
// // // // // // // // // // // // // // // // // // // // // // // // //                         {monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}
// // // // // // // // // // // // // // // // // // // // // // // // //                     </span>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <button onClick={handleNextMonth} style={calendarStyles.navButton}>→</button>
// // // // // // // // // // // // // // // // // // // // // // // // //                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                 <div style={calendarStyles.weekdays}>
// // // // // // // // // // // // // // // // // // // // // // // // //                     {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
// // // // // // // // // // // // // // // // // // // // // // // // //                         <div key={day} style={calendarStyles.weekday}>{day}</div>
// // // // // // // // // // // // // // // // // // // // // // // // //                     ))}
// // // // // // // // // // // // // // // // // // // // // // // // //                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                 <div style={calendarStyles.days}>
// // // // // // // // // // // // // // // // // // // // // // // // //                     {days.map((date, idx) => (
