// // // // // // // // // // // // // // // // // // // // // // // // //                                 ...(date && date.toDateString() === new Date().toDateString() ? calendarStyles.today : {})
// // // // // // // // // // // // // // // // // // // // // // // // //                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                             onClick={() => date && handleDateSelect(date)}
// // // // // // // // // // // // // // // // // // // // // // // // //                         >
// // // // // // // // // // // // // // // // // // // // // // // // //                             {date ? date.getDate() : ''}
// // // // // // // // // // // // // // // // // // // // // // // // //                         </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                     ))}
// // // // // // // // // // // // // // // // // // // // // // // // //                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //             </div>
// // // // // // // // // // // // // // // // // // // // // // // // //         );
// // // // // // // // // // // // // // // // // // // // // // // // //     };

