// // // // // // // // // // // // // // // // // // // // // // // // //                             type="text"
// // // // // // // // // // // // // // // // // // // // // // // // //                             value={invoice.order_no}
// // // // // // // // // // // // // // // // // // // // // // // // //                             onChange={(e) => setInvoice(prev => ({ ...prev, order_no: e.target.value }))}
// // // // // // // // // // // // // // // // // // // // // // // // //                             placeholder="Reference"
// // // // // // // // // // // // // // // // // // // // // // // // //                             onKeyDown={(e) => handleKeyNavigation(e, orderNoRef, customerRef, dateRef)}
// // // // // // // // // // // // // // // // // // // // // // // // //                             style={styles.input}
// // // // // // // // // // // // // // // // // // // // // // // // //                         />
// // // // // // // // // // // // // // // // // // // // // // // // //                     </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <div style={styles.formGroup}>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <label style={styles.label}>Customer * (Alt+4)</label>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <div style={styles.dropdown}>
// // // // // // // // // // // // // // // // // // // // // // // // //                             <input
// // // // // // // // // // // // // // // // // // // // // // // // //                                 ref={customerRef}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 data-customer-input
// // // // // // // // // // // // // // // // // // // // // // // // //                                 type="text"
// // // // // // // // // // // // // // // // // // // // // // // // //                                 placeholder="Search customer by name or mobile..."
// // // // // // // // // // // // // // // // // // // // // // // // //                                 value={invoice.customer_name}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 onChange={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     setInvoice(prev => ({ ...prev, customer_name: e.target.value, account_id: '' }));
// // // // // // // // // // // // // // // // // // // // // // // // //                                     setShowCustomerDropdown(true);
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 onFocus={() => setShowCustomerDropdown(true)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     if (e.key === 'Enter' && showCustomerDropdown && focusedCustomerIndex >= 0) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         const selected = filteredAccounts[focusedCustomerIndex];
// // // // // // // // // // // // // // // // // // // // // // // // //                                         if (selected) handleCustomerSelect(selected);
// // // // // // // // // // // // // // // // // // // // // // // // //                                     } else if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                         notesRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                     } else if (e.key === 'ArrowDown' && showCustomerDropdown) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                         setFocusedCustomerIndex(prev => prev < filteredAccounts.length - 1 ? prev + 1 : prev);
// // // // // // // // // // // // // // // // // // // // // // // // //                                     } else if (e.key === 'ArrowUp' && showCustomerDropdown) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                         setFocusedCustomerIndex(prev => prev > 0 ? prev - 1 : -1);
// // // // // // // // // // // // // // // // // // // // // // // // //                                     } else if (e.key === 'Escape') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         setShowCustomerDropdown(false);
// // // // // // // // // // // // // // // // // // // // // // // // //                                     } else {
// // // // // // // // // // // // // // // // // // // // // // // // //                                         handleKeyNavigation(e, customerRef, notesRef, orderNoRef);
// // // // // // // // // // // // // // // // // // // // // // // // //                                     }
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 style={styles.input}
// // // // // // // // // // // // // // // // // // // // // // // // //                             />
// // // // // // // // // // // // // // // // // // // // // // // // //                             {showCustomerDropdown && filteredAccounts.length > 0 && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <div ref={customerDropdownRef} style={{
// // // // // // // // // // // // // // // // // // // // // // // // //                                     ...styles.dropdownList,
// // // // // // // // // // // // // // // // // // // // // // // // //                                     position: 'fixed',
// // // // // // // // // // // // // // // // // // // // // // // // //                                     top: customerRef.current ? customerRef.current.getBoundingClientRect().bottom + window.scrollY : 0,
// // // // // // // // // // // // // // // // // // // // // // // // //                                     left: customerRef.current ? customerRef.current.getBoundingClientRect().left + window.scrollX : 0,
// // // // // // // // // // // // // // // // // // // // // // // // //                                     width: customerRef.current ? customerRef.current.offsetWidth : '300px'
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                     {filteredAccounts.map((account, idx) => (
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <div
// // // // // // // // // // // // // // // // // // // // // // // // //                                             key={account.account_id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                             onClick={() => handleCustomerSelect(account)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                             style={{ ...styles.dropdownItem, backgroundColor: focusedCustomerIndex === idx ? '#f0f0f0' : 'white' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                             onMouseEnter={() => setFocusedCustomerIndex(idx)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                         >
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <div><strong>{account.customer_name}</strong></div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             {account.mobile_number && <small style={{ color: '#666' }}>{account.mobile_number}</small>}
// // // // // // // // // // // // // // // // // // // // // // // // //                                         </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                     ))}
// // // // // // // // // // // // // // // // // // // // // // // // //                                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                             )}
