// // // // // // // // // // // // // // // // // // // // // // // // //                     <label style={styles.label}>Notes (Alt+5)</label>
// // // // // // // // // // // // // // // // // // // // // // // // //                     <textarea
// // // // // // // // // // // // // // // // // // // // // // // // //                         ref={notesRef}
// // // // // // // // // // // // // // // // // // // // // // // // //                         value={invoice.notes}
// // // // // // // // // // // // // // // // // // // // // // // // //                         onChange={(e) => setInvoice(prev => ({ ...prev, notes: e.target.value }))}
// // // // // // // // // // // // // // // // // // // // // // // // //                         rows="2"
// // // // // // // // // // // // // // // // // // // // // // // // //                         placeholder="Additional notes..."
// // // // // // // // // // // // // // // // // // // // // // // // //                         onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                             if (e.key === 'Enter' && !e.shiftKey) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 addItemRowButtonRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                             } else {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 handleKeyNavigation(e, notesRef, addItemRowButtonRef, customerRef);
// // // // // // // // // // // // // // // // // // // // // // // // //                             }
// // // // // // // // // // // // // // // // // // // // // // // // //                         }}
