// // // // // // // // // // // // // // // // // // // // // // // // //                         ref={addItemRowButtonRef}
// // // // // // // // // // // // // // // // // // // // // // // // //                         onClick={handleAddNewRow}
// // // // // // // // // // // // // // // // // // // // // // // // //                         style={styles.addButton}
// // // // // // // // // // // // // // // // // // // // // // // // //                         onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                             if (e.key === 'Enter') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 handleAddNewRow();
// // // // // // // // // // // // // // // // // // // // // // // // //                             } else if (e.key === 'ArrowDown') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const firstItemRow = document.querySelector('[data-item-row]');
// // // // // // // // // // // // // // // // // // // // // // // // //                                 if (firstItemRow) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     const editBtn = firstItemRow.querySelector('[data-edit-btn]');
// // // // // // // // // // // // // // // // // // // // // // // // //                                     if (editBtn) editBtn.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 }
// // // // // // // // // // // // // // // // // // // // // // // // //                             } else if (e.key === 'ArrowUp') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                 discountRef.current?.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                             }
// // // // // // // // // // // // // // // // // // // // // // // // //                         }}
// // // // // // // // // // // // // // // // // // // // // // // // //                     >
// // // // // // // // // // // // // // // // // // // // // // // // //                         <FiPlus size={14} /> Add Item Row (Ctrl+Alt+N)
