// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Qty</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Rate (₨)</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellRight}>Amount (₨)</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                                 <th style={styles.tableCellCenter}>Actions</th>
// // // // // // // // // // // // // // // // // // // // // // // // //                             </tr>
// // // // // // // // // // // // // // // // // // // // // // // // //                         </thead>
// // // // // // // // // // // // // // // // // // // // // // // // //                         <tbody>
// // // // // // // // // // // // // // // // // // // // // // // // //                             {invoice.items.map((item, index) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const isEditing = editingItemId === item.id;
// // // // // // // // // // // // // // // // // // // // // // // // //                                 const validItem = item.item_id && item.quantity > 0;

// // // // // // // // // // // // // // // // // // // // // // // // //                                 if (isEditing && tempItem) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                     const dropdownPosition = getDropdownPosition(item.id);

// // // // // // // // // // // // // // // // // // // // // // // // //                                     return (
// // // // // // // // // // // // // // // // // // // // // // // // //                                         <tr key={item.id} style={{ background: '#f9f9f9', borderTop: '2px solid #2196F3' }} data-item-row>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCell}>{index + 1}</td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCell}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 <div style={styles.dropdown}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <div style={{ position: 'relative' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <FiSearch style={{ position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)', color: '#999', fontSize: '14px' }} />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <input
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             data-row-id={item.id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             data-item-search
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             type="text"
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             placeholder="Search item by name or code..."
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             value={tempItem.searchTerm || ''}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onChange={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 setTempItem(prev => ({ ...prev, searchTerm: e.target.value }));
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 setShowItemDropdown(item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onFocus={() => setShowItemDropdown(item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             onKeyDown={(e) => {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 if (e.key === 'ArrowDown' && showItemDropdown === item.id && filteredProducts.length > 0) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     setFocusedDropdownIndex(0);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Escape') {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     setShowItemDropdown(null);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Enter' && showItemDropdown === item.id && focusedDropdownIndex >= 0) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     const selected = filteredProducts[focusedDropdownIndex];
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     if (selected) handleProductSelect(selected, item.id);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Tab' && !e.shiftKey) {
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     const qtyInput = document.querySelector(`[data-qty-input="${item.id}"]`);
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     if (qtyInput) qtyInput.focus();
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 }
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             style={{ ...styles.input, paddingLeft: '32px' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         />
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     {showItemDropdown === item.id && filteredProducts.length > 0 && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         <div
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             ref={el => itemDropdownRefs.current[item.id] = el}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             style={{
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 ...styles.dropdownList,
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 position: 'fixed',
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 top: dropdownPosition.top,
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 left: dropdownPosition.left,
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 width: '300px'
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             {filteredProducts.map((product, idx) => (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 <div
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     key={product.item_id}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     onClick={() => handleProductSelect(product, item.id)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     style={{ ...styles.dropdownItem, backgroundColor: focusedDropdownIndex === idx ? '#f0f0f0' : 'white' }}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     onMouseEnter={() => setFocusedDropdownIndex(idx)}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 >
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     <div><strong>{product.item_name}</strong></div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                     <small style={{ color: '#666' }}>Code: {product.item_code} | ₨ {product.price?.toLocaleString()}</small>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                             ))}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 {tempItem.item_name && (
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     <div style={{ marginTop: '4px', fontSize: '11px', color: '#4CAF50' }}>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                         ✓ {tempItem.item_name}
// // // // // // // // // // // // // // // // // // // // // // // // //                                                     </div>
// // // // // // // // // // // // // // // // // // // // // // // // //                                                 )}
// // // // // // // // // // // // // // // // // // // // // // // // //                                             </td>
// // // // // // // // // // // // // // // // // // // // // // // // //                                             <td style={styles.tableCellRight}>
