// // // // // // // // // // // // // // // // // // // // // // // //         textarea: { padding: '8px 12px', border: '1px solid #ddd', borderRadius: '6px', fontSize: '13px', resize: 'vertical', fontFamily: 'inherit', width: '100%', boxSizing: 'border-box' },
