// // // // // // // // // // // // // // // // // // // // // // //                                                                     setShowItemDropdown(null);
// // // // // // // // // // // // // // // // // // // // // // //                                                                 } else if (e.key === 'Enter' && showItemDropdown === item.id && focusedDropdownIndex >= 0) {
// // // // // // // // // // // // // // // // // // // // // // //                                                                     e.preventDefault();
// // // // // // // // // // // // // // // // // // // // // // //                                                                     const selected = filteredProducts[focusedDropdownIndex];
// // // // // // // // // // // // // // // // // // // // // // //                                                                     if (selected) handleProductSelect(selected, item.id);
