// // // // // // // // // // // // // // // // // // // //                                                             e.preventDefault();
// // // // // // // // // // // // // // // // // // // //                                                             const rateInput = document.querySelector(`[data-rate-input="${item.id}"]`);
// // // // // // // // // // // // // // // // // // // //                                                             if (rateInput) rateInput.focus();
