// // // // // // // // // // // // // // // // // // // //                                                     {currentCustomer || <span style={{ color: '#999' }}>Click to add customer</span>}
// // // // // // // // // // // // // // // // // // // //                                                     <FiEdit2 style={styles.editIcon} size={12} />
// // // // // // // // // // // // // // // // // // // //                                                 </div>
// // // // // // // // // // // // // // // // // // // //                                             )}
